using System; using System.Drawing; using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers; using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmRegistration:StyledForm { ComboBox cmbYear=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=250};TextBox txt=new TextBox{Width=250};Label prompt=new Label{AutoSize=true};Label result=new Label{AutoSize=true,ForeColor=Color.Navy};Button next=new Button{Text="Next",Enabled=false,Width=100};public FrmRegistration(){Text="Registration Verification";Size=new Size(550,330);StartPosition=FormStartPosition.CenterParent;var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(50),WrapContents=false};p.Controls.Add(new Label{Text="Select University Year",Font=new Font("Segoe UI",13,FontStyle.Bold),AutoSize=true});cmbYear.Items.AddRange(new object[]{"First Year","Second Year","Third Year","Fourth Year","Fifth Year"});p.Controls.Add(cmbYear);p.Controls.Add(prompt);p.Controls.Add(txt);var check=new Button{Text="Check Eligibility",Width=150};p.Controls.Add(check);p.Controls.Add(result);p.Controls.Add(next);Controls.Add(p);cmbYear.SelectedIndexChanged+=delegate{prompt.Text=cmbYear.SelectedIndex==0?"Matriculation admission seat number":"Existing university roll number";next.Enabled=false;result.Text="";};check.Click+=delegate{string msg;bool ok=cmbYear.SelectedIndex==0?new AdmissionQuery().CheckAdmission(txt.Text.Trim(),out msg):new ResultQuery().CheckExisting(txt.Text.Trim(),out msg);result.Text=msg;result.ForeColor=ok?Color.Green:Color.Maroon;next.Enabled=ok;};next.Click+=delegate{var f=new FrmApplicationWizard(cmbYear.SelectedIndex+1,txt.Text.Trim());Hide();f.ShowDialog(this);Close();};cmbYear.SelectedIndex=0;} } }
